#!/usr/bin/env node
// plank-join.mjs — Shipshape plank-join checker
// Scans .feature files for scenarios, scans implementation files for @planks annotations,
// cross-references planks against step definition patterns, and reports violations.
// Returns exit code 0 if all checks pass, non-zero otherwise.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

let exitCode = 0;

// --- Helpers ---

function walkDir(dir, predicate) {
  const entries = [];
  if (!fs.existsSync(dir)) return entries;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      entries.push(...walkDir(full, predicate));
    } else if (predicate(entry)) {
      entries.push(full);
    }
  }
  return entries;
}

function readLines(filePath) {
  return fs.readFileSync(filePath, 'utf8').split('\n');
}

// --- 1. Collect scenarios from .feature files ---
// Returns Map<featureFileRelative, Map<scenarioName, tags>>
function collectScenarios(specsDir) {
  const featureFiles = walkDir(specsDir, (e) => e.name.endsWith('.feature'));
  const scenarios = new Map();

  for (const ff of featureFiles) {
    const rel = path.relative(ROOT, ff);
    const lines = readLines(ff);
    const featureScenarios = new Map();
    let currentScenario = null;
    let currentTags = [];
    let inScenario = false;

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith('@') && !trimmed.startsWith('@planks')) {
        // Tag line — collect tags for the next scenario
        const tags = trimmed.split(/\s+/).filter(t => t.startsWith('@'));
        // Could span multiple lines of tags
        if (!inScenario) {
          currentTags.push(...tags);
        }
      } else if (trimmed.startsWith('Scenario') || trimmed.startsWith('Scenario Outline')) {
        const match = trimmed.match(/^(?:Scenario Outline|Scenario):\s*(.+)/);
        if (match) {
          currentScenario = match[1].trim();
          featureScenarios.set(currentScenario, currentTags);
          inScenario = true;
        }
      } else if (trimmed.startsWith('Given') || trimmed.startsWith('When') || trimmed.startsWith('Then') || trimmed.startsWith('And') || trimmed.startsWith('But')) {
        // Step line — in scenario
      } else if (trimmed === '' || trimmed.startsWith('Feature') || trimmed.startsWith('Background') || trimmed.startsWith('Rule') || trimmed.startsWith('Example') || trimmed.startsWith('|')) {
        // Not a new scenario, keep going
      } else {
        // Could be a continuation or other content
      }
    }

    if (featureScenarios.size > 0) {
      scenarios.set(rel, featureScenarios);
    }
  }

  return scenarios;
}

// --- 2. Collect @planks and @planks-provisional annotations from implementation files ---
function collectPlanks(implDirs) {
  const planks = new Map(); // filePath -> [{line, text, type, scenarioRef}]

  for (const dir of implDirs) {
    const absDir = path.resolve(ROOT, dir);
    const files = walkDir(absDir, (e) => e.name.endsWith('.js') || e.name.endsWith('.mjs') || e.name.endsWith('.cjs'));
    for (const file of files) {
      const content = fs.readFileSync(file, 'utf8');
      const lines = content.split('\n');
      const filePlanks = [];

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        // Match @planks("pattern") in docblock comments
        let match;
        const regex1 = /@planks\(["'](.+?)["']\)/;
        match = line.match(regex1);
        if (match) {
          filePlanks.push({ line: i + 1, text: match[1], type: 'planks' });
        }
        const regex2 = /@planks-provisional\(["'](.+?)["']\)/;
        match = line.match(regex2);
        if (match) {
          filePlanks.push({ line: i + 1, scenarioRef: match[1], type: 'planks-provisional' });
        }
      }

      if (filePlanks.length > 0) {
        planks.set(file, filePlanks);
      }
    }
  }

  return planks;
}

// --- 3. Collect step definition patterns from step definition files ---
function collectStepPatterns(verificationDirs) {
  const patterns = new Set();

  for (const dir of verificationDirs) {
    const absDir = path.resolve(ROOT, dir);
    if (!fs.existsSync(absDir)) continue;
    const files = walkDir(absDir, (e) => e.name.endsWith('.js') || e.name.endsWith('.mjs') || e.name.endsWith('.cjs'));
    for (const file of files) {
      const content = fs.readFileSync(file, 'utf8');
      // Match cucumber step definition patterns: Given(/pattern/, ...) or When(/pattern/, ...) or Then(/pattern/, ...)
      const regex = /(?:Given|When|Then|And|But)\(\s*\/(.+?)\/\s*[,)]/g;
      let match;
      while ((match = regex.exec(content)) !== null) {
        patterns.add(match[1]);
      }
    }
  }

  return patterns;
}

// --- 4. Check planks ---
function checkPlanks(planks, patterns, captainScenarios, scenariosByFile) {
  const errors = [];

  for (const [file, filePlanks] of planks) {
    for (const plank of filePlanks) {
      if (plank.type === 'planks') {
        // Check pattern exists in step definitions
        if (!patterns.has(plank.text)) {
          errors.push(`MISMATCH: ${file}:${plank.line} — @planks("${plank.text}") matches no step definition pattern`);
        }
      } else if (plank.type === 'planks-provisional') {
        // Check scenario reference exists and still carries @captain
        const ref = plank.scenarioRef;
        // Form: spec.feature:Scenario Name
        const colonIdx = ref.indexOf(':');
        if (colonIdx === -1) {
          errors.push(`MALFORMED: ${file}:${plank.line} — @planks-provisional("${ref}") is not in spec.feature:Scenario Name form`);
          continue;
        }
        const specFile = ref.slice(0, colonIdx);
        const scenarioName = ref.slice(colonIdx + 1);

        const fileScenarios = scenariosByFile.get(specFile);
        if (!fileScenarios) {
          errors.push(`MISSING: ${file}:${plank.line} — @planks-provisional("${ref}") references feature file "${specFile}" which does not exist or has no scenarios`);
          continue;
        }

        if (!fileScenarios.has(scenarioName)) {
          errors.push(`MISSING: ${file}:${plank.line} — @planks-provisional("${ref}") references scenario "${scenarioName}" not found in "${specFile}"`);
          continue;
        }

        const tags = fileScenarios.get(scenarioName);
        if (!tags.includes('@captain') && !tags.includes('@captain')) {
          errors.push(`PROMOTED: ${file}:${plank.line} — @planks-provisional("${ref}") references scenario "${scenarioName}" which no longer carries @captain`);
        }
      }
    }
  }

  return errors;
}

// --- Main ---
function main() {
  const riggingPath = path.join(ROOT, 'RIGGING.md');

  // Read directories from RIGGING.md if available
  let implDirs = ['js'];
  let specsDir = path.join(ROOT, 'features');
  let verificationDirs = ['features/support'];

  if (fs.existsSync(riggingPath)) {
    const rigging = fs.readFileSync(riggingPath, 'utf8');
    const implMatch = rigging.match(/- implementation:\s+(.+)/);
    if (implMatch) {
      implDirs = implMatch[1].split('\n').map(l => l.replace('- implementation:', '').trim()).filter(Boolean);
    }
    const specsMatch = rigging.match(/- specs:\s+(.+)/);
    if (specsMatch) {
      const specsRel = specsMatch[1].trim();
      specsDir = path.resolve(ROOT, specsRel);
    }
    const verificationMatch = [...rigging.matchAll(/- verification:\s+(.+)/g)].map(m => m[1].trim()).filter(Boolean);
    if (verificationMatch.length > 0) {
      verificationDirs = verificationMatch;
    }
  }

  // Collect scenarios from feature files
  const scenariosByFile = collectScenarios(specsDir);

  // Collect all @captain scenarios for provisional plank checking
  const captainScenarios = new Set();
  for (const [file, scenarios] of scenariosByFile) {
    for (const [name, tags] of scenarios) {
      if (tags.includes('@captain')) {
        captainScenarios.add(`${file}:${name}`);
      }
    }
  }

  // For reporting: count scenarios
  let totalScenarios = 0;
  let captainCount = 0;
  for (const scenarios of scenariosByFile.values()) {
    for (const [name, tags] of scenarios) {
      totalScenarios++;
      if (tags.includes('@captain')) captainCount++;
    }
  }

  console.log(`plank-join: ${totalScenarios} scenarios found (${captainCount} @captain)`);

  // Collect step definition patterns
  const patterns = collectStepPatterns(verificationDirs);
  console.log(`plank-join: ${patterns.size} step definition patterns found`);

  // Collect planks from implementation files
  const planks = collectPlanks(implDirs);
  let plankCount = 0;
  for (const filePlanks of planks.values()) {
    plankCount += filePlanks.length;
  }
  console.log(`plank-join: ${plankCount} plank annotations found in ${planks.size} files`);

  // Check planks
  const errors = checkPlanks(planks, patterns, captainScenarios, scenariosByFile);

  if (errors.length > 0) {
    console.log('\nplank-join: ERRORS');
    for (const err of errors) {
      console.log(`  ${err}`);
    }
    exitCode = 1;
  } else {
    console.log('plank-join: all checks passed');
  }

  process.exit(exitCode);
}

main();

